//! Real host/tool/store integration driven by a deterministic local provider.
//!
//! `CSV` bytes are generated by the production `write_file` tool. `PDF`/`PPTX` bytes
//! are declared repository fixtures; this verifies delivery and persistence,
//! not a real language model or a professional document generator.

use std::fs;
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use serde_json::{Value, json};

use crate::{
    AgentHandle, AgentWorkspace, ChatLine, LlmConfig, SessionOrigin, TurnStatus,
};

const CSV: &str = "region,sales\nNorth,120\nSouth,80\n";
const SUBMISSION: u128 = 0x1234;

struct Scratch(PathBuf);

impl Scratch {
    fn new() -> Self {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "flowy-artifact-integration-{}-{stamp}",
            std::process::id()
        ));
        fs::create_dir_all(&root).unwrap();
        Self(root)
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

struct ProviderFixture {
    address: std::net::SocketAddr,
    stopped: Arc<AtomicBool>,
    phase: Arc<AtomicUsize>,
    output_root: Arc<Mutex<Option<PathBuf>>>,
    requests: Arc<Mutex<Vec<Value>>>,
    thread: Option<thread::JoinHandle<()>>,
}

enum ProviderMode {
    Delivery,
    ProjectWrite { path: String, content: String },
    DelayedText { delay_ms: u64, reply: String },
}

impl ProviderFixture {
    fn start() -> Self {
        Self::start_with(ProviderMode::Delivery)
    }

    fn start_project_write(path: &str, content: &str) -> Self {
        Self::start_with(ProviderMode::ProjectWrite {
            path: path.into(),
            content: content.into(),
        })
    }

    fn start_delayed_text(delay_ms: u64, reply: &str) -> Self {
        Self::start_with(ProviderMode::DelayedText {
            delay_ms,
            reply: reply.into(),
        })
    }

    fn start_with(mode: ProviderMode) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        listener.set_nonblocking(true).unwrap();
        let stopped = Arc::new(AtomicBool::new(false));
        let phase = Arc::new(AtomicUsize::new(0));
        let output_root = Arc::new(Mutex::new(None::<PathBuf>));
        let requests = Arc::new(Mutex::new(Vec::new()));
        let state = (
            Arc::clone(&stopped),
            Arc::clone(&phase),
            Arc::clone(&output_root),
            Arc::clone(&requests),
        );
        let thread = thread::spawn(move || {
            while !state.0.load(Ordering::SeqCst) {
                match listener.accept() {
                    Ok((mut socket, _)) => {
                        if state.0.load(Ordering::SeqCst) {
                            break;
                        }
                        // Windows accepted sockets inherit the listener's
                        // nonblocking mode. Restore blocking I/O before the
                        // bounded request read, otherwise a request accepted
                        // just before its bytes arrive is mistaken for EOF.
                        socket.set_nonblocking(false).unwrap();
                        let Some(request) = read_request(&mut socket) else {
                            continue;
                        };
                        let has_tools = request["tools"]
                            .as_array()
                            .is_some_and(|tools| !tools.is_empty());
                        state.3.lock().unwrap().push(request);
                        let (delta, finish_reason) = if has_tools {
                            let index = state.1.fetch_add(1, Ordering::SeqCst);
                            match &mode {
                                ProviderMode::Delivery => {
                                    let root =
                                        state.2.lock().unwrap().clone().expect(
                                            "host assigned output root",
                                        );
                                    match index {
                                        0 => tool_delta(
                                            "fixture-write-csv",
                                            "write_file",
                                            json!({
                                                "path": root.join("sales.csv").display().to_string(), "content": CSV
                                            }),
                                        ),
                                        1 => tool_delta(
                                            "fixture-publish-csv",
                                            "publish_file",
                                            json!({
                                                "path": "sales.csv", "delivery_key": "sales", "display_name": "Sales report.csv"
                                            }),
                                        ),
                                        2 => tool_delta(
                                            "fixture-publish-pdf",
                                            "publish_file",
                                            json!({
                                                "path": "sample.pdf", "delivery_key": "pdf-fixture"
                                            }),
                                        ),
                                        3 => tool_delta(
                                            "fixture-publish-pptx",
                                            "publish_file",
                                            json!({
                                                "path": "sample.pptx", "delivery_key": "pptx-fixture"
                                            }),
                                        ),
                                        _ => (
                                            json!({"role":"assistant","content":"Fixture delivery complete."}),
                                            "stop",
                                        ),
                                    }
                                }
                                ProviderMode::ProjectWrite {
                                    path,
                                    content,
                                } => {
                                    if index == 0 {
                                        tool_delta(
                                            "fixture-project-write",
                                            "write_file",
                                            json!({ "path": path, "content": content }),
                                        )
                                    } else {
                                        (
                                            json!({"role":"assistant","content":"Project file written."}),
                                            "stop",
                                        )
                                    }
                                }
                                ProviderMode::DelayedText {
                                    delay_ms,
                                    reply,
                                } => {
                                    thread::sleep(Duration::from_millis(
                                        *delay_ms,
                                    ));
                                    (
                                        json!({"role":"assistant","content": reply}),
                                        "stop",
                                    )
                                }
                            }
                        } else {
                            // Automatic conversation-title requests are
                            // independent of the actual delivery turn.
                            (
                                json!({"role":"assistant","content":"Artifact fixture delivery"}),
                                "stop",
                            )
                        };
                        let _ = write_stream(&mut socket, delta, finish_reason);
                    }
                    Err(error)
                        if error.kind() == std::io::ErrorKind::WouldBlock =>
                    {
                        thread::sleep(Duration::from_millis(5));
                    }
                    Err(error) => {
                        panic!("local fixture provider failed: {error}")
                    }
                }
            }
        });
        Self {
            address,
            stopped,
            phase,
            output_root,
            requests,
            thread: Some(thread),
        }
    }

    fn config(&self) -> LlmConfig {
        LlmConfig {
            api_key: Some("isolated-integration-fixture-token".into()),
            provider: "openai".into(),
            model: "fixture-delivery-model".into(),
            base_url: format!("http://{}/v1", self.address),
            ..LlmConfig::default()
        }
    }
}

impl Drop for ProviderFixture {
    fn drop(&mut self) {
        self.stopped.store(true, Ordering::SeqCst);
        let _ = TcpStream::connect(self.address);
        if let Some(thread) = self.thread.take() {
            thread.join().unwrap();
        }
    }
}

fn tool_delta(
    call_id: &str,
    name: &str,
    arguments: Value,
) -> (Value, &'static str) {
    (
        json!({
            "role": "assistant",
            "tool_calls": [{
                "index": 0, "id": call_id, "type": "function",
                "function": { "name": name, "arguments": arguments.to_string() }
            }]
        }),
        "tool_calls",
    )
}

fn read_request(socket: &mut TcpStream) -> Option<Value> {
    socket.set_read_timeout(Some(Duration::from_secs(5))).ok()?;
    let mut bytes = Vec::new();
    let header_end = loop {
        if let Some(index) =
            bytes.windows(4).position(|window| window == b"\r\n\r\n")
        {
            break index + 4;
        }
        assert!(
            bytes.len() < 2 * 1024 * 1024,
            "fixture request exceeded its limit"
        );
        let mut buffer = [0_u8; 4096];
        let read = socket.read(&mut buffer).ok()?;
        if read == 0 {
            return None;
        }
        bytes.extend_from_slice(&buffer[..read]);
    };
    let headers = std::str::from_utf8(&bytes[..header_end]).ok()?;
    let length = headers.lines().find_map(|line| {
        let (name, value) = line.split_once(':')?;
        if name.eq_ignore_ascii_case("content-length") {
            value.trim().parse::<usize>().ok()
        } else {
            None
        }
    })?;
    assert!(length < 2 * 1024 * 1024, "fixture body exceeded its limit");
    while bytes.len() < header_end + length {
        let mut buffer = [0_u8; 4096];
        let read = socket.read(&mut buffer).ok()?;
        if read == 0 {
            return None;
        }
        bytes.extend_from_slice(&buffer[..read]);
    }
    serde_json::from_slice(&bytes[header_end..header_end + length]).ok()
}

fn write_stream(
    socket: &mut TcpStream,
    delta: Value,
    finish_reason: &str,
) -> std::io::Result<()> {
    let delta = json!({
        "id":"fixture-response", "object":"chat.completion.chunk", "created":1,
        "model":"fixture-delivery-model", "choices":[{"index":0,"delta":delta,"finish_reason":null}]
    });
    let finished = json!({
        "id":"fixture-response", "object":"chat.completion.chunk", "created":1,
        "model":"fixture-delivery-model", "choices":[{"index":0,"delta":{},"finish_reason":finish_reason}]
    });
    let body = format!("data: {delta}\n\ndata: {finished}\n\ndata: [DONE]\n\n");
    let headers = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    socket.write_all(headers.as_bytes())?;
    socket.write_all(body.as_bytes())?;
    socket.flush()
}

fn wait_for_completion(
    handle: &AgentHandle,
    provider: &ProviderFixture,
    root: &std::path::Path,
    session: &str,
) {
    let deadline = Instant::now() + Duration::from_secs(15);
    while handle.turn_status().is_busy() && Instant::now() < deadline {
        thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(
        handle.turn_status(),
        TurnStatus::Completed,
        "host turn failed: {:?}; durable core status: {:?}; scripted requests: {:?}",
        handle.lines(),
        flowy_agent_core::SessionIndex::load(root).map(|history| history
            .get(session)
            .map(|record| record.status.clone())),
        provider
            .requests
            .lock()
            .unwrap()
            .iter()
            .map(|request| json!({
                "model": request["model"],
                "messages": request["messages"],
                "tool_count": request["tools"].as_array().map_or(0, Vec::len)
            }))
            .collect::<Vec<_>>()
    );
    assert!(provider.phase.load(Ordering::SeqCst) >= 5);
}

fn artifact_ids(handle: &AgentHandle) -> Vec<String> {
    handle
        .lines()
        .into_iter()
        .filter_map(|line| {
            if let ChatLine::Artifact { artifact_id } = line {
                Some(artifact_id)
            } else {
                None
            }
        })
        .collect()
}

/// Windows can briefly report a sharing violation when another reader (the
/// conversation-file import or the on-access scanner) still has the source
/// open. The test edits files the turn just delivered, so retry the two
/// user-simulation operations instead of making the suite timing-sensitive.
fn write_with_retry(path: &std::path::Path, bytes: &[u8]) {
    let deadline = Instant::now() + Duration::from_secs(2);
    loop {
        match fs::write(path, bytes) {
            Ok(()) => return,
            Err(_) if Instant::now() < deadline => {
                thread::sleep(Duration::from_millis(25));
            }
            Err(error) => {
                panic!("write {} failed after retries: {error}", path.display())
            }
        }
    }
}

fn remove_with_retry(path: &std::path::Path) {
    let deadline = Instant::now() + Duration::from_secs(2);
    loop {
        match fs::remove_file(path) {
            Ok(()) => return,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return;
            }
            Err(_) if Instant::now() < deadline => {
                thread::sleep(Duration::from_millis(25));
            }
            Err(error) => {
                panic!(
                    "remove {} failed after retries: {error}",
                    path.display()
                )
            }
        }
    }
}

#[test]
fn scripted_host_delivers_real_csv_and_document_fixtures_through_publish_file()
{
    let scratch = Scratch::new();
    let provider = ProviderFixture::start();
    let handle = AgentHandle::with_config(scratch.0.clone(), provider.config());
    let session = handle.create_home_session().unwrap();
    let history = flowy_agent_core::SessionIndex::load(&scratch.0).unwrap();
    let record = history.get(&session).unwrap();
    assert_eq!(record.origin, SessionOrigin::Home);
    let output = record
        .workspace
        .as_ref()
        .unwrap()
        .root
        .join("outputs")
        .join(format!("submission-{SUBMISSION:032x}"));
    fs::create_dir_all(&output).unwrap();
    *provider.output_root.lock().unwrap() = Some(output.clone());
    let fixtures = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../flowy-studio/examples/fixtures/preview");
    let pdf = fs::read(fixtures.join("sample.pdf")).unwrap();
    let pptx = fs::read(fixtures.join("sample.pptx")).unwrap();
    assert!(pdf.starts_with(b"%PDF-"));
    assert!(pptx.starts_with(b"PK\x03\x04"));
    fs::write(output.join("sample.pdf"), &pdf).unwrap();
    fs::write(output.join("sample.pptx"), &pptx).unwrap();
    // The deck enters the delivery gate through its verification report; the
    // scripted host does not generate a deck, so the report is fixed setup.
    let gate = crate::delivery::DeliveryStore::new(scratch.0.join("delivery"));
    gate.record_report(&output.join("sample.pptx"), Vec::new(), 1)
        .unwrap();

    handle.submit_chat(SUBMISSION, "Create the sales CSV and publish it with the declared PDF and PPTX fixtures.").unwrap();
    wait_for_completion(&handle, &provider, &scratch.0, &session);
    let ids = artifact_ids(&handle);
    assert_eq!(
        ids.len(),
        3,
        "the three real publish calls must produce three cards"
    );
    let store = handle.artifact_store().unwrap();
    let artifacts = store.list().unwrap();
    assert_eq!(artifacts.len(), 3);
    let mut expected = std::collections::BTreeMap::from([
        ("Sales report.csv", CSV.as_bytes().to_vec()),
        ("sample.pdf", pdf),
        ("sample.pptx", pptx),
    ]);
    for artifact in &artifacts {
        let receipt = &artifact.manifest.receipt;
        assert_eq!(receipt.session_id, session);
        assert!(ids.contains(&receipt.artifact_id));
        let bytes = expected.remove(receipt.display_name.as_str()).unwrap();
        assert_eq!(store.read_payload(&receipt.artifact_id).unwrap(), bytes);
    }
    assert!(expected.is_empty());
    let csv_id = artifacts
        .iter()
        .find(|artifact| {
            artifact.manifest.receipt.display_name == "Sales report.csv"
        })
        .unwrap()
        .manifest
        .receipt
        .artifact_id
        .clone();
    let original_receipt =
        store.get(&csv_id).unwrap().unwrap().manifest.receipt;
    store.set_favorite(&csv_id, true).unwrap();
    store.trash(&csv_id).unwrap();

    write_with_retry(&output.join("sales.csv"), b"later overwritten source");
    remove_with_retry(&output.join("sample.pdf"));
    assert_eq!(store.read_payload(&csv_id).unwrap(), CSV.as_bytes());
    assert_eq!(
        store.get(&csv_id).unwrap().unwrap().manifest.receipt.sha256,
        original_receipt.sha256
    );
    let export = scratch.0.join("saved-report.csv");
    store.copy_to(&csv_id, &export).unwrap();
    assert_eq!(fs::read(&export).unwrap(), CSV.as_bytes());
    drop(store);
    drop(handle);
    drop(provider);

    let restored =
        AgentHandle::with_config(scratch.0.clone(), LlmConfig::default());
    restored.select_session(&session).unwrap();
    assert_eq!(artifact_ids(&restored), ids);
    let store = restored.artifact_store().unwrap();
    let favorite = store.get(&csv_id).unwrap().unwrap();
    assert!(favorite.preference.favorite);
    assert!(favorite.preference.trashed_at_ms.is_some());
    store.restore_from_trash(&csv_id).unwrap();
    assert_eq!(store.read_payload(&csv_id).unwrap(), CSV.as_bytes());
    restored.delete_session(&session).unwrap();
    assert!(!restored.source_deleted(&session));
    assert!(!restored.source_available(&session));
    assert_eq!(store.list().unwrap().as_slice(), []);
    assert!(store.read_payload(&csv_id).is_err());
    assert_eq!(fs::read(&export).unwrap(), CSV.as_bytes());
    drop(restored);

    let reopened =
        AgentHandle::with_config(scratch.0.clone(), LlmConfig::default());
    assert!(!reopened.source_deleted(&session));
    assert!(reopened.list_sessions().is_empty());
    let store = reopened.artifact_store().unwrap();
    assert_eq!(store.list().unwrap().as_slice(), []);
    assert!(store.read_payload(&csv_id).is_err());
}

#[test]
fn completed_project_turn_imports_successful_write_file() {
    const MARKDOWN: &str = "# 锂电池\n\nProject note.\n";
    let scratch = Scratch::new();
    let project = scratch.0.join("project");
    fs::create_dir_all(&project).unwrap();
    let project = fs::canonicalize(project).unwrap();
    let provider = ProviderFixture::start_project_write("notes.md", MARKDOWN);
    let handle = AgentHandle::with_config(scratch.0.clone(), provider.config());
    handle.set_workspace_for_new_sessions(Some(AgentWorkspace {
        project_id: "project-1".into(),
        root: project.clone(),
    }));
    handle.set_origin_for_new_sessions(SessionOrigin::Project {
        project_id: Some("project-1".into()),
    });
    let session = handle.create_session().unwrap();
    handle
        .submit_chat(0x2345, "Write the project note.")
        .unwrap();

    let deadline = Instant::now() + Duration::from_secs(15);
    while handle.turn_status().is_busy() && Instant::now() < deadline {
        thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(handle.turn_status(), TurnStatus::Completed);
    while handle.artifacts().unwrap().is_empty() && Instant::now() < deadline {
        thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(
        fs::read(project.join("notes.md")).unwrap(),
        MARKDOWN.as_bytes()
    );
    let records = handle.artifacts().unwrap();
    assert_eq!(records.len(), 1);
    assert_eq!(records[0].manifest.receipt.session_id, session);
    assert_eq!(
        records[0].manifest.origin,
        SessionOrigin::Project {
            project_id: Some("project-1".into())
        }
    );
    assert_eq!(records[0].manifest.source_relative_path, "notes.md");
    assert_eq!(
        handle
            .read_artifact(&records[0].manifest.receipt.artifact_id)
            .unwrap(),
        MARKDOWN.as_bytes()
    );
}

#[test]
fn kernel_review_failed_turn_on_restart_stays_retryable_not_completed() {
    use flowy_agent_core::{
        AcceptanceQueue, ContentBlock, Message, MessageSource, ReceiptState,
        Role, SessionIndex, SessionRecord, SubmissionOutcome, TurnState,
    };

    let scratch = Scratch::new();
    let queue = AcceptanceQueue::new(scratch.0.clone());

    // Case 1: Legacy-shaped Error session with an assistant error reply.
    let err_receipt = queue
        .accept(None, "Deliver the signed report", 1_000)
        .unwrap();
    assert!(
        queue
            .take(&err_receipt.id, "try-1", 1_001, 30)
            .unwrap()
            .is_some()
    );
    assert!(
        queue
            .bind(
                &err_receipt.id,
                "try-1",
                "session-error",
                "submission-error",
                1_002
            )
            .unwrap()
    );

    // Case 2: Session whose later turn Completed, while this earlier submission
    // explicitly recorded SubmissionOutcome::Failed.
    let earlier_fail = queue
        .accept(None, "Earlier failed work in same session", 1_010)
        .unwrap();
    assert!(
        queue
            .take(&earlier_fail.id, "try-2", 1_011, 30)
            .unwrap()
            .is_some()
    );
    assert!(
        queue
            .bind(
                &earlier_fail.id,
                "try-2",
                "session-later-ok",
                "submission-failed-first",
                1_012
            )
            .unwrap()
    );

    let mut index = SessionIndex::load(&scratch.0).unwrap();
    index.upsert(SessionRecord {
        id: "session-error".into(),
        status: TurnState::Error {
            message: "provider failed".into(),
        },
        messages: vec![
            Message {
                id: "submission-error".into(),
                role: Role::User,
                content: vec![ContentBlock::text("Deliver the signed report")],
                source: MessageSource::User,
            },
            Message {
                id: "response-error".into(),
                role: Role::Assistant,
                content: vec![ContentBlock::text(
                    "Could not complete this task",
                )],
                source: MessageSource::Model {
                    provider: "fixture".into(),
                    model: "fixture".into(),
                },
            },
        ],
        origin: SessionOrigin::Home,
        ..SessionRecord::default()
    });
    let mut outcomes = std::collections::BTreeMap::new();
    outcomes.insert(
        "submission-failed-first".to_owned(),
        SubmissionOutcome::Failed {
            message: "tool crash".to_owned(),
        },
    );
    outcomes.insert(
        "submission-second-ok".to_owned(),
        SubmissionOutcome::Completed,
    );
    index.upsert(SessionRecord {
        id: "session-later-ok".into(),
        status: TurnState::Completed,
        messages: vec![
            Message {
                id: "submission-failed-first".into(),
                role: Role::User,
                content: vec![ContentBlock::text(
                    "Earlier failed work in same session",
                )],
                source: MessageSource::User,
            },
            Message {
                id: "resp-failed-first".into(),
                role: Role::Assistant,
                content: vec![ContentBlock::text("failed")],
                source: MessageSource::Model {
                    provider: "fixture".into(),
                    model: "fixture".into(),
                },
            },
            Message {
                id: "submission-second-ok".into(),
                role: Role::User,
                content: vec![ContentBlock::text("follow up")],
                source: MessageSource::User,
            },
            Message {
                id: "resp-second-ok".into(),
                role: Role::Assistant,
                content: vec![ContentBlock::text("ok")],
                source: MessageSource::Model {
                    provider: "fixture".into(),
                    model: "fixture".into(),
                },
            },
        ],
        submission_outcomes: outcomes,
        origin: SessionOrigin::Home,
        ..SessionRecord::default()
    });
    index.save(&scratch.0).unwrap();

    let reopened = AgentHandle::with_config(
        scratch.0.clone(),
        LlmConfig {
            api_key: None,
            ..Default::default()
        },
    );
    assert_eq!(
        reopened.receipt_state(&err_receipt.id),
        Some(ReceiptState::Retrying),
        "an Error session must never be reconciled as Completed on restart"
    );
    assert_eq!(
        reopened.receipt_state(&earlier_fail.id),
        Some(ReceiptState::Retrying),
        "an explicitly Failed submission must stay retryable even if a later turn Completed"
    );
    assert!(
        reopened
            .artifact_store()
            .unwrap()
            .committed_ids()
            .unwrap()
            .is_empty()
    );
}

#[test]
fn forced_breakpoint_1_bind_failure_and_stale_lease_never_dispatch_engine() {
    use flowy_agent_core::AcceptanceQueue;

    // Subcase A: journal write failure during `queue.bind` -> zero provider calls.
    let scratch = Scratch::new();
    let provider = ProviderFixture::start_delayed_text(10, "should not run");
    let handle = AgentHandle::with_config(scratch.0.clone(), provider.config());
    let _session = handle.create_home_session().unwrap();
    let _receipt = handle
        .accept_deferred("must not run on bind error")
        .unwrap();
    let journal_path = AcceptanceQueue::path(&scratch.0);
    let orig_perms = fs::metadata(&journal_path).unwrap().permissions();
    handle.set_before_accepted_bind_hook(Some(Arc::new(move |_| {
        let mut perms = fs::metadata(&journal_path).unwrap().permissions();
        perms.set_readonly(true);
        fs::set_permissions(&journal_path, perms).unwrap();
    })));
    let err = handle
        .run_accepted_once()
        .expect_err("bind error must fail closed");
    assert_eq!(err, "notice.storage_error");
    assert!(
        provider.requests.lock().unwrap().is_empty(),
        "failed bind must result in zero engine/provider invocations"
    );
    assert!(!handle.has_active_claim());
    // Restore original permissions so Scratch cleanup succeeds on Windows.
    let journal_path = AcceptanceQueue::path(&scratch.0);
    fs::set_permissions(&journal_path, orig_perms).unwrap();
    drop(handle);
    drop(provider);

    // Subcase B: lease cancelled/lost before `queue.bind` -> Ok(None), zero calls.
    let scratch_b = Scratch::new();
    let provider_b = ProviderFixture::start_delayed_text(10, "should not run");
    let handle_b =
        AgentHandle::with_config(scratch_b.0.clone(), provider_b.config());
    let _session_b = handle_b.create_home_session().unwrap();
    let _receipt_b = handle_b.accept_deferred("cancelled before bind").unwrap();
    let root_b = scratch_b.0.clone();
    handle_b.set_before_accepted_bind_hook(Some(Arc::new(move |receipt_id| {
        let queue = AcceptanceQueue::new(root_b.clone());
        assert!(queue.cancel(receipt_id, 9_999_999_999_999).unwrap());
    })));
    assert!(
        handle_b
            .run_accepted_once()
            .expect("stale bind returns Ok(None)")
            .is_none()
    );
    assert!(
        provider_b.requests.lock().unwrap().is_empty(),
        "stale lease bind must result in zero engine/provider invocations"
    );
    assert!(!handle_b.has_active_claim());
}

#[test]
fn concurrent_session_switch_between_bind_and_submit_keeps_work_on_session_a() {
    use std::sync::Barrier;

    let scratch = Scratch::new();
    let provider = ProviderFixture::start_project_write(
        "outputs/from-session-a.md",
        "# Bound to A\n",
    );
    let handle = AgentHandle::with_config(scratch.0.clone(), provider.config());
    let session_a = handle.create_home_session().unwrap();
    let session_b = handle.create_home_session().unwrap();
    handle.select_session(&session_a).unwrap();
    let receipt = handle.accept_deferred("execute strictly in A").unwrap();
    assert_eq!(receipt.session_hint.as_deref(), Some(session_a.as_str()));

    let enter_barrier = Arc::new(Barrier::new(2));
    let resume_barrier = Arc::new(Barrier::new(2));
    let hook_enter = Arc::clone(&enter_barrier);
    let hook_resume = Arc::clone(&resume_barrier);
    handle.set_before_accepted_submit_hook(Some(Arc::new(move |_bound| {
        hook_enter.wait();
        hook_resume.wait();
    })));

    let switcher_handle = handle.clone();
    let target_b = session_b.clone();
    let switcher = thread::spawn(move || {
        enter_barrier.wait();
        switcher_handle.select_session(&target_b).unwrap();
        assert_eq!(
            switcher_handle.active_session_id().as_deref(),
            Some(target_b.as_str())
        );
        resume_barrier.wait();
    });

    let run = handle
        .run_accepted_once()
        .expect("dispatch")
        .expect("claimed");
    switcher.join().unwrap();
    handle.set_before_accepted_submit_hook(None);

    assert_eq!(run.session_id, session_a);
    assert_eq!(
        handle.active_session_id().as_deref(),
        Some(session_b.as_str()),
        "background dispatch must never hijack the user's active session B"
    );

    let deadline = Instant::now() + Duration::from_secs(15);
    while handle.has_busy_session() && Instant::now() < deadline {
        thread::sleep(Duration::from_millis(10));
    }
    assert!(!handle.has_busy_session());
    handle.finish_accepted(true).unwrap();

    let history = flowy_agent_core::SessionIndex::load(&scratch.0).unwrap();
    let rec_a = history.get(&session_a).expect("session A exists");
    let rec_b = history.get(&session_b).expect("session B exists");
    assert!(
        rec_a
            .messages
            .iter()
            .any(|msg| msg.text().contains("execute strictly in A")),
        "session A must receive the bound prompt"
    );
    assert!(
        rec_b.messages.is_empty(),
        "session B must remain completely untouched, got {:?}",
        rec_b.messages
    );
    let artifacts = handle.artifacts().unwrap();
    assert!(
        artifacts
            .iter()
            .all(|item| item.manifest.receipt.session_id == session_a),
        "all artifacts must belong strictly to session A"
    );
}

#[test]
fn long_running_accepted_turn_renews_lease_past_initial_expiry() {
    use flowy_agent_core::{AcceptanceQueue, ReceiptState};

    let scratch = Scratch::new();
    let provider = ProviderFixture::start_delayed_text(450, "done slowly");
    let handle = AgentHandle::with_config(scratch.0.clone(), provider.config());
    let _session = handle.create_home_session().unwrap();
    handle.set_accepted_lease_ms_for_test(150);

    let receipt = handle
        .accept_deferred("slow turn needing heartbeat")
        .unwrap();
    let _run = handle
        .run_accepted_once()
        .expect("dispatch")
        .expect("claimed");

    // Wait well past the initial 150ms lease expiry while the 450ms turn runs.
    thread::sleep(Duration::from_millis(260));
    assert_eq!(
        handle.receipt_state(&receipt.id),
        Some(ReceiptState::Running),
        "heartbeat must keep the active claim Running past initial lease expiry"
    );
    assert!(
        handle.pending_acceptances().is_empty(),
        "a heartbeated running receipt must not re-enter pending"
    );

    let deadline = Instant::now() + Duration::from_secs(15);
    while handle.has_busy_session() && Instant::now() < deadline {
        thread::sleep(Duration::from_millis(10));
    }
    assert!(!handle.has_busy_session());
    handle.finish_accepted(true).unwrap();
    assert_eq!(
        handle.receipt_state(&receipt.id),
        Some(ReceiptState::Completed)
    );
    let journal =
        fs::read_to_string(AcceptanceQueue::path(&scratch.0)).unwrap();
    assert!(
        journal.contains(r#""event":"renewed""#),
        "acceptance journal must contain lease renewal entries: {journal}"
    );
}
